def parse(path):
    lines = path.read_text(encoding="utf-8").splitlines()
    title = lines[0]
    source = next(line for line in lines if line.startswith("> 원본 PDF 범위:"))
    start = next((i + 1 for i, line in enumerate(lines) if line == "<!-- TOC END -->"), 1)
    sections, current = OrderedDict(), None
    for line in lines[start:]:
        if line.startswith("## "):
            current = line[3:]
            sections[current] = []
        elif current is not None:
            sections[current].append(line)
    return title, source, sections


def append(out, label, content, subheading=True):
    if subheading:
        out += ["### " + label, ""]
    while content and not content[0].strip(): content = content[1:]
    while content and not content[-1].strip(): content = content[:-1]
    out += content + [""]


def main():
    for chapter, groups in CONFIG.items():
        path = next(NOTES.glob(f"{chapter:02d}_*.md"))
        title, source, sections = parse(path)
        out = [title, "", source + " · 원문 순서 재편집", "", "<!-- TOC START -->", "<!-- TOC END -->", ""]
        used = set()
        for heading, labels, memory in groups:
            out += ["## " + heading, "", "> **암기 한 줄:** " + memory, ""]
            present = [x for x in labels if x in sections]
            for label in present:
                append(out, label, list(sections[label]), len(present) > 1 or label != heading)
                used.add(label)
        supplements = [x for x in SUPPLEMENT.get(chapter, []) if x in sections and x not in used]
        if supplements:
            out += ["## 보충 학습", "", "> 원문 절 순서를 모두 학습한 뒤 이해와 문제 적용력을 높이는 확장 내용이다.", ""]
            for label in supplements:
                append(out, label, list(sections[label]))
                used.add(label)
        problem = next((x for x in sections if "교재 확인문제" in x or x == "6. 교재 확인문제"), None)
        if problem:
            out += ["## 교재 문제와 해설", "", "> 문제는 원문 단원 말미의 출제 순서대로 정리했다.", ""]
            append(out, problem, list(sections[problem]), False)
            used.add(problem)
        remaining = [x for x in sections if x not in used and x != "목차"]
        if remaining:
            out += ["## 추가 보충", ""]
            for label in remaining: append(out, label, list(sections[label])); used.add(label)
        path.write_text("\n".join(out).rstrip() + "\n", encoding="utf-8")
        print(path.name)


if __name__ == "__main__": main()
